import numpy as np

def feature(moves, owner, points, adjacency, homes, turn):
    """Opponent BFS reach-delay (capped at 3) to empty cells when candidate is removed, points-weighted, normalised."""
    N = owner.shape[0]
    k = moves.shape[0]
    total_pts = float(points.sum())
    denom = 3.0 * total_pts if total_pts > 0 else 1.0

    opp_cells = np.where(owner == -1)[0]
    empty_cells = np.where(owner == 0)[0]
    traversable = (owner == 0) | (owner == -1)

    # Precompute neighbour lists once.
    nbrs = [np.where(adjacency[u])[0] for u in range(N)]

    def bfs_dist(blocked_cell):
        dist = np.full(N, -1, dtype=np.int64)
        queue = []
        for s in opp_cells:
            if s == blocked_cell:
                continue
            dist[s] = 0
            queue.append(s)
        head = 0
        while head < len(queue):
            u = queue[head]
            head += 1
            du = dist[u]
            if du >= 3:
                continue
            for v in nbrs[u]:
                if v == blocked_cell:
                    continue
                if not traversable[v]:
                    continue
                if dist[v] == -1:
                    dist[v] = du + 1
                    queue.append(v)
        return dist

    d_base = bfs_dist(-1)

    values = np.zeros(k, dtype=np.float64)
    for i in range(k):
        c = int(moves[i])
        d_cut = bfs_dist(c)
        s = 0.0
        for v in empty_cells:
            if v == c:
                continue
            db = d_base[v]
            dc = d_cut[v]
            if db == -1:
                db = 3
            if dc == -1:
                dc = 3
            delay = dc - db
            if delay < 0:
                delay = 0
            elif delay > 3:
                delay = 3
            if delay:
                s += points[v] * delay
        values[i] = s / denom

    return values

import numpy as np

def feature(moves, owner, homes, points, adjacency, turn):
    """Exact minimax value (my final score minus opponent's, normalised) of claiming each candidate, resolved to the end of the game when <=4 empty cells remain, else 0."""
    k = moves.shape[0]
    E = int((owner == 0).sum())
    if E > 4:
        return np.zeros(k, dtype=float)

    N = owner.shape[0]
    total = float(points.sum()) + 1.0
    adj = adjacency
    pts = points

    def resolve(o, m, p):
        # claim m for player p, then resolve flips (no chaining)
        o = o.copy()
        o[m] = p
        opp = -p
        opp_home = homes[1] if p == 1 else homes[0]
        # opponent cells adjacent to m
        cand = np.where((o == opp) & adj[m])[0]
        for v in cand:
            if v == opp_home:
                continue
            nb = adj[v]
            mine = int((nb & (o == p)).sum())
            theirs = int((nb & (o == opp)).sum())
            if mine >= theirs:
                o[v] = p
        return o

    def mm(o, p, depth):
        if int((o == 0).sum()) == 0:
            return (float(pts[o == 1].sum()) - float(pts[o == -1].sum())) / total
        if depth > 4:
            return (float(pts[o == 1].sum()) - float(pts[o == -1].sum())) / total
        empties = np.where(o == 0)[0]
        # legal moves for p: empty cells adjacent to a p-cell
        legal = []
        for e in empties:
            if (adj[e] & (o == p)).any():
                legal.append(e)
        if not legal:
            # check other player
            other_legal = False
            for e in empties:
                if (adj[e] & (o == -p)).any():
                    other_legal = True
                    break
            if not other_legal:
                return (float(pts[o == 1].sum()) - float(pts[o == -1].sum())) / total
            return mm(o, -p, depth + 1)
        if p == 1:
            best = -np.inf
            for m in legal:
                v = mm(resolve(o, m, p), -p, depth + 1)
                if v > best:
                    best = v
            return best
        else:
            best = np.inf
            for m in legal:
                v = mm(resolve(o, m, p), -p, depth + 1)
                if v < best:
                    best = v
            return best

    vals = np.zeros(k, dtype=float)
    for i in range(k):
        c = int(moves[i])
        o2 = resolve(owner, c, 1)
        vals[i] = mm(o2, -1, 1)
    return vals

import numpy as np

def feature(moves, owner, homes, points, adjacency, turn):
    """Tempo-discounted strictly-won empty points (col0) and its opponent mirror (col1), cut at distance 2."""
    N = owner.shape[0]
    total = float(points.sum())
    if total <= 0:
        total = 1.0
    k = moves.shape[0]
    out = np.zeros((k, 2), dtype=np.float64)
    if k == 0:
        return out

    adj = adjacency.astype(bool)
    opp_home = int(homes[1])
    pts = points.astype(np.float64)

    # Precompute neighbour lists once (Python lists of arrays) for BFS.
    nbrs = [np.nonzero(adj[i])[0] for i in range(N)]

    for idx in range(k):
        c = int(moves[idx])
        owner_after = owner.copy()
        owner_after[c] = 1
        # Flips: opponent non-home cells adjacent to c.
        for x in nbrs[c]:
            if owner_after[x] != -1 or x == opp_home:
                continue
            m = 0
            o = 0
            for y in nbrs[x]:
                if y == c:
                    m += 1  # c counted once as mine
                elif owner_after[y] == 1:
                    m += 1
                elif owner_after[y] == -1:
                    o += 1
            if m >= o:
                owner_after[x] = 1

        # BFS through empty cells only, starting from each side's territory.
        INF = 10**6
        d_m = np.full(N, INF, dtype=np.int64)
        d_o = np.full(N, INF, dtype=np.int64)

        qm = []
        qo = []
        for i in range(N):
            if owner_after[i] == 0:
                # distance 1 if adjacent to my/opp territory
                if np.any(owner_after[nbrs[i]] == 1):
                    d_m[i] = 1
                    qm.append(i)
                if np.any(owner_after[nbrs[i]] == -1):
                    d_o[i] = 1
                    qo.append(i)

        head = 0
        while head < len(qm):
            u = qm[head]
            head += 1
            du = d_m[u]
            for v in nbrs[u]:
                if owner_after[v] == 0 and d_m[v] > du + 1:
                    d_m[v] = du + 1
                    qm.append(v)
        head = 0
        while head < len(qo):
            u = qo[head]
            head += 1
            du = d_o[u]
            for v in nbrs[u]:
                if owner_after[v] == 0 and d_o[v] > du + 1:
                    d_o[v] = du + 1
                    qo.append(v)

        col0 = 0.0
        col1 = 0.0
        for v in range(N):
            if owner_after[v] != 0:
                continue
            dm = d_m[v]
            do = d_o[v]
            if dm < do and dm <= 2:
                col0 += pts[v] / (1.0 + dm)
            elif do < dm and do <= 2:
                col1 -= pts[v] / (1.0 + do)

        out[idx, 0] = col0 / total
        out[idx, 1] = col1 / total

    return out
